INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (1, 'en', 'Allow User Abort', 'Allows or prevents users from stopping a running script.', 16);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (2, 'en', 'Commit Transaction', 'Saves all record changes and ends the current transaction.', 17);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (3, 'en', 'Configure Local Notification', 'Queues or clears a local notification.', 18);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (4, 'en', 'Configure NFC Reading', 'Scans or stops scanning for NFC (near field communication) tags.', 19);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (5, 'en', 'Configure Persistent Data', 'Sets or deletes an entry in the persistent data store.', 20);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (6, 'en', 'Configure Region Monitor Script', 'Configures a specified script to run when an iOS or iPadOS device enters or exits a specified region.', 21);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (7, 'en', 'Else', 'Performs an alternate set of script steps when an If or Else If script step evaluates to false.', 22);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (8, 'en', 'Else If', 'Evaluates a Boolean calculation and performs a conditional action based on that evaluation, like If.', 23);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (9, 'en', 'End If', 'Marks the end of an If script step structure.', 24);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (10, 'en', 'End Loop', 'Marks the end of a Loop script structure.', 25);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (11, 'en', 'Exit Loop If', 'Exits a loop if the specified calculation is true (not zero).', 26);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (12, 'en', 'Exit Script', 'Forces the running script, sub-script, or external script to stop immediately.', 27);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (13, 'en', 'Halt Script', 'Forces all scripts, sub-scripts, or external scripts running in the current FileMaker application to stop immediately.', 28);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (14, 'en', 'If', 'Evaluates a Boolean calculation and performs a conditional action based on that evaluation.', 29);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (15, 'en', 'Install OnTimer Script', 'Runs a specified script at the specified interval.', 30);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (16, 'en', 'Loop', 'Repeats a set of script steps, to perform batch processes.', 31);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (17, 'en', 'Open Transaction', 'Starts a transaction; subsequent record changes are held in the transaction until a Commit Transaction or Revert Transaction script step is performed.', 32);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (18, 'en', 'Pause/Resume Script', 'Pauses a script so the user can perform other tasks in the current window.', 33);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (19, 'en', 'Perform Script', 'Performs a script specified from a list or calculated by name.', 34);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (20, 'en', 'Perform Script On Server', 'Performs a script specified from a list or calculated by name on the server that is hosting the current file.', 35);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (21, 'en', 'Perform Script On Server with Callback', 'Performs a script on the server that is hosting the current file without pausing the client and performs the specified callback script on the client when the server script is done.', 36);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (22, 'en', 'Revert Transaction', 'Returns all records changed in the transaction to their original state and ends the current transaction.', 37);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (23, 'en', 'Set Error Capture', 'Suppresses or enables normal alert messages displayed by FileMaker clients.', 38);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (24, 'en', 'Set Error Logging', 'Controls whether errors are logged while the current file''s scripts are running.', 39);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (25, 'en', 'Set Layout Object Animation', 'Enables or disables animations while a script is running.', 40);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (26, 'en', 'Set Revert Transaction on Error', 'Controls whether transactions are immediately reverted when an error occurs.', 41);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (27, 'en', 'Set Variable', 'Sets a local or global variable to a specified value.', 42);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (28, 'en', 'Trigger Claris Connect Flow', 'Triggers a Claris Connect flow and sends the specified JSON data.', 43);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (29, 'en', 'Close Popover', 'Closes an open popover in the window in which the script step runs.', 44);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (30, 'en', 'Enter Browse Mode', 'Switches to Browse mode.', 45);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (31, 'en', 'Enter Find Mode', 'Switches to Find mode.', 46);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (32, 'en', 'Enter Preview Mode', 'Switches to Preview mode.', 47);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (33, 'en', 'Go to Field', 'Moves to the specified field on the current layout.', 48);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (34, 'en', 'Go to Layout', 'Switches to the specified layout.', 49);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (35, 'en', 'Go to List of Records', 'Goes to a layout and returns the found set specified by a list of record IDs.', 50);
