INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (37, 'en', 'Go to Object', 'Moves to the specified object on the current layout.', 52);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (38, 'en', 'Go to Portal Row', 'Navigates among the rows in the active portal.', 53);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (39, 'en', 'Go to Previous Field', 'Moves to the previous field in the tab order of the current layout.', 54);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (40, 'en', 'Go to Record/Request/Page', 'Moves to a record or a report page, or displays a find request.', 55);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (41, 'en', 'Go to Related Record', 'Goes to the current related record(s) in a related table.', 56);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (42, 'en', 'Clear', 'Deletes the contents of the specified field in the current record.', 57);
