INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (46, 'en', 'Perform Find/Replace', 'Finds/replaces data according to the options in the Perform Find/Replace Options dialog box.', 61);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (47, 'en', 'Select All', 'Selects the entire contents of the active field.', 62);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (48, 'en', 'Set Selection', 'Designates a selection or cursor location in a field.', 63);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (49, 'en', 'Undo/Redo', 'Reverses, restores, or switches between the most recently performed actions in the file.', 64);
