INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (53, 'en', 'Insert Current Date', 'Pastes the current system date into a field or variable.', 68);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (54, 'en', 'Insert Current Time', 'Pastes the current system time into a field or variable.', 69);
