INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (61, 'en', 'Insert PDF', 'Imports a PDF file or file reference into the current interactive container.', 76);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (62, 'en', 'Insert Picture', 'Imports a graphic from another file into the current container field.', 77);
