INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (73, 'en', 'Delete Portal Row', 'Deletes the selected portal row.', 88);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (74, 'en', 'Delete Record/Request', 'Deletes the current record or find request.', 89);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (75, 'en', 'Duplicate Record/Request', 'Duplicates the current record or the current find request.', 90);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (76, 'en', 'Export Records', 'Exports records to a specified file.', 91);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (77, 'en', 'Import Records', 'Imports records from a specified file or data source.', 92);
