INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (98, 'en', 'Adjust Window', 'Hides or changes the size of a window.', 113);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (99, 'en', 'Arrange All Windows', 'Adjusts the size and location of all open windows.', 114);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (100, 'en', 'Close Window', 'Closes the currently active window or any other window by name or UUID.', 115);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (101, 'en', 'Freeze Window', 'Stops updating the active window.', 116);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (102, 'en', 'Move/Resize Window', 'Adjusts the size or location of the chosen window.', 117);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (103, 'en', 'New Window', 'Creates a new window based on the foreground window.', 118);
