INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (107, 'en', 'Set Window Title', 'Changes the title of a window.', 122);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (108, 'en', 'Set Zoom Level', 'Enlarges or reduces the image on the screen.', 123);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (109, 'en', 'Show/Hide Menubar', 'Shows or hides the menu bar.', 124);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (110, 'en', 'Show/Hide Text Ruler', 'Shows or hides the text ruler.', 125);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (111, 'en', 'Show/Hide Toolbars', 'Shows or hides the FileMaker Pro status toolbar and the FileMaker Go toolbar and editing toolbar.', 126);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (112, 'en', 'View As', 'Displays data in the specified format.', 127);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (113, 'en', 'Close Data File', 'Closes an open data file.', 128);
