INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (124, 'en', 'Print', 'Prints information that is in the current FileMaker Pro file.', 139);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (125, 'en', 'Print Setup', 'Sets print options, such as paper size and orientation, which can be stored with this script step.', 140);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (126, 'en', 'Read from Data File', 'Reads data from an open data file.', 141);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (127, 'en', 'Recover File', 'Recovers a damaged FileMaker Pro file.', 142);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (128, 'en', 'Rename File', 'Renames a file.', 143);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (129, 'en', 'Save a Copy as', 'Saves a copy of the current file.', 144);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (130, 'en', 'Save a Copy as XML', 'Saves a copy of an open file as an XML representation of the schema, layouts, and scripts.', 145);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (131, 'en', 'Set Data File Position', 'Sets the read-write position in an open data file.', 146);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (132, 'en', 'Set Multi-User', 'Allows or disallows network access to a file.', 147);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (133, 'en', 'Set Use System Formats', 'Sets the formats either to those stored with the file or to the current system formats.', 148);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (134, 'en', 'Write to Data File', 'Writes data to an open data file.', 149);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (135, 'en', 'Add Account', 'Adds a new account.', 150);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (136, 'en', 'Change Password', 'Changes the password for the current FileMaker file account.', 151);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (137, 'en', 'Delete Account', 'Deletes an account.', 152);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (138, 'en', 'Enable Account', 'Enables or disables an account.', 153);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (139, 'en', 'Re-Login', 'Signs in again to an open file with a different FileMaker file account, external server account, or the Guest account.', 154);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (140, 'en', 'Reset Account Password', 'Resets the password of a FileMaker file account.', 155);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (141, 'en', 'Configure AI Account', 'Sets up an AI account to use by name, given a model provider (or endpoint) and an API key.', 156);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (142, 'en', 'Configure Machine Learning Model', 'Loads a Core ML (Machine Learning) model and prepares it for use.', 157);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (143, 'en', 'Configure Prompt Template', 'Sets up a prompt template to use by name in other AI script steps, given a model provider and predefined prompts you can customize.', 158);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (144, 'en', 'Configure RAG Account', 'Sets up a RAG account to use by name, given an endpoint and an API key.', 159);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (145, 'en', 'Configure Regression Model', 'Trains, saves, loads, and unloads a regression model. Trains a model based on embedding vectors for text data and numeric target data.', 160);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (146, 'en', 'Fine-Tune Model', 'Fine-tunes a model with the specified training data set.', 161);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (147, 'en', 'Generate Response from Model', 'Gets a text response from an AI model given a user prompt.', 162);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (148, 'en', 'Insert Embedding', 'Sends input data to an embedding model and inserts the returned vector representation into a field or variable.', 163);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (149, 'en', 'Insert Embedding in Found Set', 'For every record in the found set, sends data from a source field to an embedding model and inserts the returned vector representation into a target field.', 164);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (150, 'en', 'Insert Image Caption', 'Sends an image to an image captioning model and inserts the returned caption into a field or variable.', 165);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (151, 'en', 'Insert Image Captions in Found Set', 'For every record in the found set, sends an image from a source field to an image captioning model and inserts the returned caption into a target field.', 166);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (152, 'en', 'Perform Find by Natural Language', 'Sends a natural language prompt and a list of fields on the current layout to a model, which returns a FileMaker find request, and performs a find.', 167);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (153, 'en', 'Perform RAG Action', 'Sends a prompt to, or adds and removes data from, a RAG space on the AI model server specified by a RAG account.', 168);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (154, 'en', 'Perform Semantic Find', 'Performs a semantic find in a target field for the specified text, image, or embedding vectors.', 169);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (155, 'en', 'Perform SQL Query by Natural Language', 'Sends a natural language prompt and database schema to a model, which sends back an SQL query to get a result from the database to use in its response.', 170);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (156, 'en', 'Set AI Call Logging', 'Controls whether details of AI calls are saved to a log file.', 171);
