INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (159, 'en', 'Check Selection', 'Uses the spelling checker to check the selected text.', 174);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (160, 'en', 'Correct Word', 'Opens the Spelling dialog box so the user can correct a misspelled word.', 175);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (161, 'en', 'Edit User Dictionary', 'Opens the User Dictionary dialog box.', 176);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (162, 'en', 'Select Dictionaries', 'Opens the Select Dictionaries dialog box.', 177);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (163, 'en', 'Set Dictionary', 'Changes Main Spelling Dictionary and User Spelling dictionary.', 178);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (164, 'en', 'Spelling Options', 'Opens the File Options dialog box to the Spelling tab.', 179);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (165, 'en', 'Append PDF', 'Appends PDF pages to the file opened by the Open PDF script step or created by the Create PDF script step.', 180);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (166, 'en', 'Cancel PDF', 'Closes the open PDF in memory without saving it.', 181);
