INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (168, 'en', 'Create PDF', 'Creates an empty PDF file in memory. Add pages using script steps such as Append PDF, then close and save the file using the Close PDF script step.', 183);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (169, 'en', 'Open PDF', 'Opens a PDF file. Add pages using script steps such as Append PDF, then close and save the file using the Close PDF script step.', 184);
