INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (171, 'en', 'Save Records as PDF', 'Saves records to a specified PDF file.', 186);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (172, 'en', 'Open Edit Saved Finds', 'Opens the Edit Saved Finds dialog box.', 187);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (173, 'en', 'Open Favorites', 'Opens the Favorites window.', 188);
