INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (175, 'en', 'Open Find/Replace', 'Opens the Find/Replace dialog box.', 190);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (176, 'en', 'Open Help', 'Opens the onscreen Help.', 191);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (177, 'en', 'Open Hosts', 'Opens the Hosts dialog box.', 192);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (178, 'en', 'Open Manage Containers', 'Opens the Manage Containers dialog box.', 193);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (179, 'en', 'Open Manage Data Sources', 'Opens the Manage External Data Sources dialog box.', 194);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (180, 'en', 'Open Manage Database', 'Opens the Manage Database dialog box.', 195);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (181, 'en', 'Open Manage Layouts', 'Opens the Manage Layouts dialog box.', 196);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (182, 'en', 'Open Manage Themes', 'Opens the Manage Themes dialog box.', 197);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (183, 'en', 'Open Manage Value Lists', 'Opens the Manage Value Lists dialog box.', 198);
