INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (185, 'en', 'Open Script Workspace', 'Opens the Script Workspace.', 200);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (186, 'en', 'Open Sharing', 'Opens the FileMaker Network Settings dialog box.', 201);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (187, 'en', 'Open Upload To Host', 'Opens the Upload to Host dialog box.', 202);
