INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (193, 'en', 'Beep', 'Plays a system beep sound.', 208);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (194, 'en', 'Dial Phone', 'Dials a phone from within a script.', 209);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (195, 'en', 'Enable Touch Keyboard', 'Enables or disables the touch keyboard.', 210);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (196, 'en', 'Execute FileMaker Data API', 'Executes a FileMaker Data API request.', 211);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (197, 'en', 'Execute SQL', 'Executes any SQL statement on an ODBC data source.', 212);
