INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (202, 'en', 'Install Menu Set', 'Changes the menu set based on conditions established in the script.', 217);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (203, 'en', 'Install Plug-In File', 'Installs or updates a plug-in file from a container field onto your computer.', 218);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (204, 'en', 'Open URL', 'Allows the user to open a URL.', 219);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (205, 'en', 'Perform AppleScript (macOS)', 'Sends AppleScript commands to another application.', 220);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (206, 'en', 'Perform JavaScript in Web Viewer', 'Performs a JavaScript function in a web viewer.', 221);
