INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (212, 'en', 'Send Mail', 'Sends an email message through an email application or via SMTP.', 227);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (213, 'en', 'Set Session Identifier', 'Sets an identifier for the user''s current session.', 228);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (214, 'en', 'Set Web Viewer', 'Controls the specified web viewer.', 229);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (215, 'en', 'Show Custom Dialog', 'Displays a custom message dialog box, with custom text and labels.', 230);
INSERT INTO "script_step_localizations" ("script_step_id", "locale", "name", "purpose", "help_page_id") VALUES (216, 'en', 'Speak (macOS)', 'Produces speech from text.', 231);
